// Settings for the AWS staging deployment (DEC-0020). Nothing here is secret:
// database passwords are generated by CloudFormation and the application keys
// are generated on the host (deploy/ec2/refresh.sh), both into Secrets Manager.
export const config = {
  /** The only region the AWS organisation's service control policy allows. */
  region: "eu-north-1",
  /** Public GitHub repository the host fetches its deployment files from, pinned to a commit. */
  repository: "ayenisholah/perpeto-backend",
  /** Public API hostname. DNS is at the registrar and is pointed at the Elastic IP by hand. */
  domain: "api.perpeto.xyz",
  /**
   * x86_64, because CI publishes an amd64 image. CPU credits are pinned to
   * standard so a busy engine is throttled rather than billed for surplus credits.
   */
  instanceType: "t3.small",
  /**
   * Amazon Linux 2023 x86_64 (al2023-ami-2023.12.20261120.0-kernel-6.18-x86_64).
   * Pinned so a new AMI never silently replaces the host and its database.
   * Changing it replaces the instance: take a backup first.
   */
  amiId: "ami-083dedce92603a2ad",
  rootVolumeGiB: 30,
  secretPrefix: "perpeto/staging",
  logGroup: "/perpeto/staging",
  tags: { project: "perpeto", environment: "staging", managedBy: "cdk" },
} as const;

/** Database role passwords, generated by CloudFormation (alphanumeric, URL-safe). */
export const DATABASE_SECRETS = ["POSTGRES_PASSWORD", "MIGRATOR_PASSWORD", "APP_PASSWORD"] as const;

/**
 * Application keys. Created as `{}` and filled once by the host, which needs
 * formats CloudFormation cannot generate (base64 of 32 random bytes, and a
 * deployment token whose SHA-256 goes in runtime.env).
 */
export const KEYS_SECRET = "KEYS";
